const DEFAULTS = {"name":"Abdulhafiz Juraev","role":"Junior Data Analyst","intro":"I turn data into meaningful insights. I enjoy working with SQL and real-world data to solve problems and create value.","aboutTitle":"A little<br>about me.","about":"The best dashboards are built long before the first chart.\n\nI enjoy the work behind the insight: understanding the shape of the data, deciding what a metric really means, and building a model that makes the answer easier to trust.\n\nIn my retail analytics project, that meant keeping returns and cancellations visible, documenting assumptions, and making the path from raw records to reporting clear.","skills":["SQL Server","T-SQL","Power BI","Data Modeling","Data Quality"],"projects":[{"title":"Online Retail Analytics Warehouse","category":"END-TO-END DATA PROJECT","description":"A transaction dataset becomes an analytics-ready warehouse. I built a Bronze → Silver → Gold pipeline, defined a clear sales model, and prepared a Power BI reporting foundation.","tags":["SQL Server","T-SQL","Power BI","Data Quality"],"link":"docs/project_documentation.md","linkText":"Explore project documentation","image":"","imageAlt":""}],"experience":[],"education":[],"email":"jurayevabdulhafiz@gmail.com","phone":"+393513828554","location":"Messina, Italy","linkedin":"","github":"","contactTitle":"Let’s work together.","contactNote":"I’m always open to discussing new opportunities, interesting projects, or just talking about data.","photo":"data:image/jpeg;base64,","availability":"Open to opportunities"};
const KEY='abdulhafiz-portfolio-v2';
let data=loadData(), currentTab='profile';
function loadData(){try{return {...structuredClone(DEFAULTS),...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{return structuredClone(DEFAULTS)}}
function save(){renderSite();markDirty()}
function markDirty(){const button=document.getElementById('saveChanges');if(button){button.disabled=false;button.textContent='Save changes ↻'}}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function safeUrl(v=''){const s=String(v).trim();if(/^(https?:\/\/|mailto:|tel:|\/|\.\.?\/|#)/i.test(s))return s;if(/^(www\.)?[a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)+(?:[/:?#][^\s]*)?$/i.test(s))return`https://${s}`;return'#'}
function rich(v=''){return esc(v).replace(/&lt;br\s*\/?&gt;/gi,'<br>').replace(/&lt;em&gt;/gi,'<em>').replace(/&lt;\/em&gt;/gi,'</em>')}
function safeImage(v=''){return /^data:image\/(png|jpeg|webp|gif);base64,/i.test(String(v))?v:''}
function skillLogo(skill){const s=skill.toLowerCase();const brands=[[/python/,['python','3776AB']],[/sql server|microsoft sql|\bt-sql\b/,['microsoftsqlserver','CC2927']],[/power\s?bi/,['powerbi','F2C811']],[/excel/,['microsoftexcel','217346']],[/postgres/,['postgresql','4169E1']],[/mysql/,['mysql','4479A1']],[/sqlite/,['sqlite','003B57']],[/pandas/,['pandas','150458']],[/numpy/,['numpy','013243']],[/jupyter/,['jupyter','F37626']],[/tableau/,['tableau','E97627']],[/javascript|\bjs\b/,['javascript','F7DF1E']],[/typescript|\bts\b/,['typescript','3178C6']],[/\bc\b|c programming/,['c','A8B9CC']],[/java(?!script)/,['java','ED8B00']],[/html/,['html5','E34F26']],[/css/,['css3','1572B6']],[/github/,['github','181717']],[/\bgit\b/,['git','F05032']],[/azure/,['microsoftazure','0078D4']],[/aws|amazon web/,['amazonaws','232F3E']],[/powerpoint/,['microsoftpowerpoint','B7472A']],[/r programming|\br language\b/,['r','276DC3']]];const match=brands.find(([re])=>re.test(s));return match?{url:`https://cdn.simpleicons.org/${match[1][0]}/${match[1][1]}`,fallback:match[1][0].slice(0,1).toUpperCase()}:null}
function skillFallback(skill){const s=skill.toLowerCase();if(/sql|database|query/.test(s))return'▤';if(/analysis|analytics|visual|report|power bi/.test(s))return'▥';if(/quality|testing|validation/.test(s))return'✓';if(/model|engineering|architecture/.test(s))return'◫';if(/communication|team/.test(s))return'◌';if(/problem|thinking/.test(s))return'✦';return'✳'}
function renderSite(){
 document.title=`${data.name||'Portfolio'} — ${data.role||'Portfolio'}`;
 document.querySelector('meta[name="description"]').content=`${data.name||'Portfolio'} — ${data.role||'Personal portfolio'}`;
 document.getElementById('brand').innerHTML=esc(initials(data.name));document.getElementById('brandName').textContent=data.name||'';document.getElementById('footerBrand').innerHTML=`${esc(initials(data.name))}<span>.</span>`;
 const nameParts=(data.name||'').trim().split(/\s+/);document.getElementById('heroName').innerHTML=`${esc(nameParts.shift()||'')}<br><em>${esc(nameParts.join(' '))}</em>`;
 document.getElementById('roleLabel').textContent=(data.role||'PORTFOLIO').toUpperCase();document.getElementById('intro').textContent=data.intro||'';
 const portrait=document.getElementById('heroPortrait'),portraitSrc=safeImage(data.photo);portrait.src=portraitSrc;portrait.alt=portraitSrc?`Portrait of ${data.name}`:'';portrait.hidden=!portraitSrc;document.getElementById('portraitFallback').hidden=!!portraitSrc;
 document.getElementById('heroSkills').innerHTML=data.skills.slice(0,5).map(s=>`<b>${esc(s)}</b>`).join('');
 document.getElementById('socialLinks').innerHTML=[['LinkedIn','linkedin','in'],['GitHub','github','GH'],['Email',data.email,'✉']].filter(([,url])=>url).map(([label,url,icon])=>`<a href="${esc(label==='Email'?`mailto:${url}`:safeUrl(url))}" aria-label="${label}" title="${label}" target="${label==='Email'?'_self':'_blank'}" rel="noreferrer">${icon}</a>`).join('');
 const skillsList=document.getElementById('skillsList');skillsList.innerHTML=data.skills.length?data.skills.map((s,i)=>{const brand=skillLogo(s);return `<div class="skill-chip"><span class="skill-index">${i+1}.</span><span class="skill-icon">${brand?`<img class="skill-logo" src="${brand.url}" alt="" loading="lazy"><span class="skill-fallback" hidden>${brand.fallback}</span>`:`<span class="skill-fallback">${skillFallback(s)}</span>`}</span><span class="skill-name">${esc(s)}</span></div>`}).join(''):'<p class="empty-state">Add your skills in Edit portfolio.</p>';skillsList.querySelectorAll('.skill-logo').forEach(img=>img.addEventListener('error',()=>{img.hidden=true;img.nextElementSibling.hidden=false},{once:true}));
 document.getElementById('aboutTitle').innerHTML=rich(data.aboutTitle||'A little<br>about me.');
 document.getElementById('aboutText').innerHTML=(data.about||'').split(/\n\s*\n/).map((p,i)=>`<p${i===0?' class="about-lead"':''}>${esc(p).replace(/\n/g,'<br>')}</p>`).join('');
 document.getElementById('projectsList').innerHTML=data.projects.length?data.projects.map((p,i)=>{const cover=safeImage(p.image);return `<article class="project-card"><div class="project-visual ${cover?'has-project-image':''}" ${cover?`style="background-image:linear-gradient(180deg,#172b2740,#172b2770),url('${cover}')"`:''}><div class="visual-top"><span>${esc((p.title||'PROJECT').toUpperCase())}</span><span>PROJECT ${i+1}</span></div>${!cover?'<div class="pipeline"><div class="layer raw"><small>1. PLAN</small><strong>Explore</strong><span>Understand</span><i>↓</i></div><div class="layer clean"><small>2. BUILD</small><strong>Develop</strong><span>Transform</span><i>↓</i></div><div class="layer gold"><small>3. SHARE</small><strong>Deliver</strong><span>Impact</span><i>✳</i></div></div>':`<div class="image-caption">${esc(p.imageAlt||p.title)}</div>`}<div class="visual-foot"><span>${esc((p.tags||[]).slice(0,3).join(' · ').toUpperCase())}</span><span>SELECTED PROJECT</span></div></div><div class="project-info"><div class="project-title"><div><p class="eyebrow">${esc(p.category||'PROJECT')}</p><h3>${esc(p.title)}</h3></div><span class="project-number">${i+1}.</span></div><p>${esc(p.description)}</p><div class="tags">${(p.tags||[]).map(t=>`<span>${esc(t.toUpperCase())}</span>`).join('')}</div>${p.link?`<a class="project-link" href="${esc(safeUrl(p.link))}" target="_blank" rel="noreferrer">${esc(p.linkText||'View project')} <span>↗</span></a>`:''}</div></article>`}).join(''):'<p class="empty-state">No projects yet. Add your first project from Edit portfolio.</p>';
 renderTimeline('experience',data.experience);renderTimeline('education',data.education);
 document.getElementById('contactTitle').textContent=data.contactTitle||'Let’s work together.';document.getElementById('contactNote').textContent=data.contactNote||'';
 document.getElementById('availabilityTitle').textContent=data.availability||'Open to opportunities';
 document.getElementById('availabilityDescription').textContent=data.contactNote||'';
 const info=[['Email',data.email,'✉',data.email?`mailto:${data.email}`:''],['Phone',data.phone,'☎',data.phone?`tel:${data.phone}`:''],['Location',data.location,'⌖',''],['LinkedIn',data.linkedin,'in',data.linkedin?safeUrl(data.linkedin):''],['GitHub',data.github,'GH',data.github?safeUrl(data.github):'']].filter(([,value])=>value);
 document.getElementById('contactDetails').innerHTML=info.length?info.map(([label,value,icon,url])=>`<div class="contact-detail"><span>${icon}</span><div><b>${esc(label)}</b>${url?`<a href="${esc(url)}" ${label==='LinkedIn'||label==='GitHub'?'target="_blank" rel="noreferrer"':''}>${esc(value)}</a>`:`<small>${esc(value)}</small>`}</div></div>`).join(''):'<p class="empty-state small">Add your contact details in Edit portfolio.</p>';
 const cvButtons=[document.getElementById('headerCV'),document.getElementById('heroCV')];cvButtons.forEach(a=>{a.href='#';a.removeAttribute('download');a.classList.remove('disabled');a.removeAttribute('aria-disabled')});
 document.getElementById('statProjects').textContent=String(data.projects.length);document.getElementById('statSkills').textContent=String(data.skills.length);document.getElementById('statExperience').textContent=String(data.experience.length);document.getElementById('statAvailability').textContent=data.availability||'Available';document.getElementById('copyright').textContent=`© ${new Date().getFullYear()} ${(data.name||'').toUpperCase()}`;
}
function initials(name){return String(name||'AJ').trim().split(/\s+/).slice(0,2).map(w=>w[0]||'').join('').toUpperCase()||'AJ'}
function renderTimeline(type,items){document.getElementById(type+'List').innerHTML=items.length?items.map(it=>`<article class="timeline-item"><span class="timeline-date">${esc(it.dates||'')}</span><h4>${esc(it.title||'')}</h4><b>${esc(it.place||'')}</b>${it.description?`<p>${esc(it.description)}</p>`:''}</article>`).join(''):'<p class="empty-state small">No entries yet. Add your details in Edit portfolio → Skills &amp; career.</p>'}
function openEditor(){document.getElementById('editor').classList.add('open');document.getElementById('editor').setAttribute('aria-hidden','false');document.getElementById('editorBackdrop').hidden=false;renderEditor()}
function closeEditor(){document.getElementById('editor').classList.remove('open');document.getElementById('editor').setAttribute('aria-hidden','true');document.getElementById('editorBackdrop').hidden=true}
function input(label,key,value,help='',type='text'){return `<label class="field"><span>${label}</span><input data-key="${key}" type="${type}" value="${esc(value||'')}" autocomplete="off">${help?`<small>${help}</small>`:''}</label>`}
function area(label,key,value,help=''){return `<label class="field"><span>${label}</span><textarea data-key="${key}" rows="4">${esc(value||'')}</textarea>${help?`<small>${help}</small>`:''}</label>`}
function renderEditor(){document.querySelectorAll('.editor-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===currentTab));const root=document.getElementById('editorContent');
 if(currentTab==='profile')root.innerHTML=`<h3>Profile</h3>${input('Full name','name',data.name)}${input('Role / headline label','role',data.role)}${area('Short introduction','intro',data.intro)}${area('About me (separate paragraphs with a blank line)','about',data.about)}${input('About section heading (HTML allowed)','aboutTitle',data.aboutTitle)}<label class="field"><span>Profile photo</span><input id="photoFile" type="file" accept="image/*"><small>Image stays in this browser. Use a square photo for best results.</small></label>${data.photo?`<div class="photo-preview"><img src="${safeImage(data.photo)}" alt="Current profile"><button data-action="remove-photo">Remove photo</button></div>`:''}<p class="format-hint">Download CV creates a PDF from your saved profile, skills, experience, education, and projects.</p>${input('Email address','email',data.email,'Used for contact links and the message form.','email')}${input('Phone number','phone',data.phone)}${input('Location','location',data.location)}${input('LinkedIn URL','linkedin',data.linkedin)}${input('GitHub URL','github',data.github)}${input('Availability label','availability',data.availability)}`;
 else if(currentTab==='projects')root.innerHTML=`<div class="editor-title-row"><h3>Your projects <span>${data.projects.length}</span></h3><button class="add-button" data-action="add-project">+ Add project</button></div>${data.projects.map((p,i)=>`<details class="project-editor" ${i===0?'open':''}><summary><span>${i+1}. ${esc(p.title||'Untitled project')}</span><span class="summary-mark">⌄</span></summary><div class="project-fields">${input('Project title',`projects.${i}.title`,p.title)}${input('Category',`projects.${i}.category`,p.category)}${area('Description',`projects.${i}.description`,p.description)}${input('Skills / tools (comma separated)',`projects.${i}.tags`,(p.tags||[]).join(', '))}${input('Project link (URL or relative path)',`projects.${i}.link`,p.link)}${input('Link label',`projects.${i}.linkText`,p.linkText)}<label class="field"><span>Project cover image</span><input data-project-file="${i}" type="file" accept="image/*"><small>Optional. Kept in this browser.</small></label>${p.image?`<button data-action="remove-project-image" data-index="${i}" class="subtle-button">Remove cover image</button>`:''}<button data-action="delete-project" data-index="${i}" class="delete-button">Delete this project</button></div></details>`).join('')||'<p class="empty-state">Add your first project with the button above.</p>'}`;
 else root.innerHTML=`<h3>Skills &amp; career</h3>${area('Skills & tools (one per line or comma separated)','skills',data.skills.join(', '))}<p class="format-hint">Experience and education: one entry per line as <code>Title | Organization | Dates | Short description</code></p>${area('Experience','experience',data.experience.map(formatEntry).join('\n'))}${area('Education','education',data.education.map(formatEntry).join('\n'))}${input('Contact section heading','contactTitle',data.contactTitle)}${area('Contact message','contactNote',data.contactNote)}`;
}
function formatEntry(x){return [x.title,x.place,x.dates,x.description].join(' | ')}
function parseEntries(s){return s.split('\n').map(l=>l.trim()).filter(Boolean).map(l=>{const [title='',place='',dates='',description='']=l.split('|').map(v=>v.trim());return{title,place,dates,description}})}
function pdfText(value){return String(value??'').replace(/[’‘ʻʼ]/g,"'").replace(/[–—]/g,'-').replace(/•/g,'-').replace(/→/g,'>').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^\x20-\x7E]/g,'').replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)')}
function makeCVPdf(profile){
 const W=595,H=842,M=48,ink='0.10 0.16 0.18',brown='0.42 0.27 0.18',muted='0.36 0.38 0.39';
 const pages=[[]];let page=pages[0],y=0;
 const txt=(text,size=10,font='F1',color=ink,x=M,top=y)=>page.push(`BT /${font} ${size} Tf ${color} rg 1 0 0 1 ${x} ${H-top-size} Tm (${pdfText(text)}) Tj ET`);
 const rule=(top)=>page.push(`${brown} RG 0.7 w ${M} ${H-top} m ${W-M} ${H-top} l S`);
 page.push(`0.42 0.27 0.18 rg 0 ${H-142} ${W} 142 re f`);
 txt(profile.name||'Portfolio',27,'F2','1 1 1',M,35);
 txt(profile.role||'Professional Profile',12,'F1','0.96 0.91 0.85',M,76);
 const contacts=[profile.email,profile.phone,profile.location].filter(Boolean).join('   |   ');
 if(contacts)txt(contacts,9,'F1','1 1 1',M,106);
 y=164;
 function nextPage(){page=[];pages.push(page);y=52;txt(profile.name||'Portfolio',12,'F2',brown,M,30);txt('CURRICULUM VITAE',8,'F1',muted,W-M-110,33);rule(49);y=67}
 function ensure(h){if(y+h>H-52)nextPage()}
 function paragraph(value,size=10,font='F1',color=ink){const max=Math.max(35,Math.floor((W-2*M)/(size*.53)));const words=pdfText(value).split(/\s+/);let line='';for(const word of words){const test=line?`${line} ${word}`:word;if(test.length>max&&line){ensure(size+6);txt(line,size,font,color,M,y);y+=size+5;line=word}else line=test}if(line){ensure(size+6);txt(line,size,font,color,M,y);y+=size+5}}
 function section(title){ensure(36);y+=8;txt(title.toUpperCase(),11,'F2',brown,M,y);y+=17;rule(y);y+=11}
 function entries(items){for(const item of items||[]){ensure(42);txt(item.title||'Entry',11,'F2',ink,M,y);y+=15;const detail=[item.place,item.dates].filter(Boolean).join('   |   ');if(detail){paragraph(detail,9,'F3',muted)}if(item.description)paragraph(item.description,10,'F1',ink);y+=7}}
 if(profile.intro||profile.about){section('Profile');paragraph(profile.intro||'');if(profile.about)paragraph(profile.about,10,'F1',ink)}
 if(profile.skills?.length){section('Skills & Tools');paragraph(profile.skills.join('  |  '),10,'F1',ink)}
 if(profile.experience?.length){section('Experience');entries(profile.experience)}
 if(profile.education?.length){section('Education');entries(profile.education)}
 if(profile.projects?.length){section('Selected Projects');for(const project of profile.projects){ensure(42);txt(project.title||'Project',11,'F2',ink,M,y);y+=15;if(project.category)paragraph(project.category,9,'F3',muted);if(project.description)paragraph(project.description,10,'F1',ink);if(project.tags?.length)paragraph(`Tools: ${project.tags.join(', ')}`,9,'F1',muted);y+=8}}
 if(profile.linkedin||profile.github||profile.availability){section('Additional Information');if(profile.linkedin)paragraph(`LinkedIn: ${profile.linkedin}`,9,'F1',ink);if(profile.github)paragraph(`GitHub: ${profile.github}`,9,'F1',ink);if(profile.availability)paragraph(`Availability: ${profile.availability}`,9,'F1',ink)}
 pages.forEach((commands,i)=>{commands.push(`0.80 0.75 0.70 RG 0.5 w ${M} 38 m ${W-M} 38 l S`);commands.push(`BT /F1 8 Tf ${muted} rg 1 0 0 1 ${W-M-55} 22 Tm (${i+1} / ${pages.length}) Tj ET`) });
 const refs=pages.map((_,i)=>6+i*2),objects=[];objects[1]='<< /Type /Catalog /Pages 2 0 R >>';objects[2]=`<< /Type /Pages /Kids [${refs.map(n=>`${n} 0 R`).join(' ')}] /Count ${pages.length} >>`;objects[3]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>';objects[4]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>';objects[5]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Oblique >>';
 pages.forEach((commands,i)=>{const pageId=refs[i],streamId=pageId+1,stream=commands.join('\n');objects[pageId]=`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${W} ${H}] /Resources << /Font << /F1 3 0 R /F2 4 0 R /F3 5 0 R >> >> /Contents ${streamId} 0 R >>`;objects[streamId]=`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`});
 let out='%PDF-1.4\n',offsets=[0];for(let i=1;i<objects.length;i++){if(objects[i]===undefined)continue;offsets[i]=out.length;out+=`${i} 0 obj\n${objects[i]}\nendobj\n`}
 const xref=out.length;out+=`xref\n0 ${objects.length}\n0000000000 65535 f \n`;for(let i=1;i<objects.length;i++)out+=`${String(offsets[i]||0).padStart(10,'0')} 00000 n \n`;out+=`trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;
 return new Blob([out],{type:'application/pdf'});
}
function downloadCV(){try{const blob=makeCVPdf(data),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${(data.name||'Portfolio').replace(/\s+/g,'_')}_CV.pdf`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}catch(error){console.error('CV PDF generation failed',error);alert('CV PDF could not be generated. Please try again.')}}
function setPath(path,value){const parts=path.split('.');let target=data;for(let i=0;i<parts.length-1;i++)target=target[parts[i]];let key=parts.at(-1);if(parts.length===1&&key==='skills')value=value.split(/[\n,]/).map(s=>s.trim()).filter(Boolean);if(parts.length===1&&(key==='experience'||key==='education'))value=parseEntries(value);if(parts[0]==='projects'&&parts.at(-1)==='tags')value=value.split(',').map(s=>s.trim()).filter(Boolean);target[key]=value}
document.getElementById('editorContent').addEventListener('change',async e=>{const el=e.target;if(el.matches('[data-key]')){setPath(el.dataset.key,el.value);save();if(el.dataset.key==='name'||el.dataset.key==='projects.0.title')renderEditor()}if(el.id==='photoFile'&&el.files[0]){data.photo=await compressImage(el.files[0]);save();renderEditor()}if(el.matches('[data-project-file]')&&el.files[0]){data.projects[+el.dataset.projectFile].image=await compressImage(el.files[0]);save();renderEditor()}});
document.getElementById('editorContent').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const i=+b.dataset.index;if(b.dataset.action==='add-project'){data.projects.push({title:'New project',category:'PROJECT',description:'',tags:[],link:'',linkText:'View project',image:'',imageAlt:''});save();currentTab='projects';renderEditor()}if(b.dataset.action==='delete-project'&&confirm(`Delete “${data.projects[i].title}”?`)){data.projects.splice(i,1);save();renderEditor()}if(b.dataset.action==='remove-project-image'){data.projects[i].image='';save();renderEditor()}if(b.dataset.action==='remove-photo'){data.photo='';save();renderEditor()}});
function compressImage(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const im=new Image();im.onerror=reject;im.onload=()=>{const scale=Math.min(1,1200/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.round(im.width*scale);c.height=Math.round(im.height*scale);c.getContext('2d').drawImage(im,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.82))};im.src=reader.result};reader.readAsDataURL(file)})}
document.getElementById('editorContent').addEventListener('input',e=>{const el=e.target;if(!el.matches('[data-key]'))return;setPath(el.dataset.key,el.value);renderSite();markDirty()});
document.getElementById('openEditor').addEventListener('click',openEditor);document.getElementById('closeEditor').addEventListener('click',closeEditor);document.getElementById('editorBackdrop').addEventListener('click',closeEditor);document.querySelector('.editor-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b){currentTab=b.dataset.tab;renderEditor()}});
document.getElementById('exportData').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='portfolio-backup.json';a.click();URL.revokeObjectURL(a.href)});
document.getElementById('saveChanges').addEventListener('click',()=>{try{localStorage.setItem(KEY,JSON.stringify(data));location.reload()}catch{alert('Could not save. The browser may be out of storage space.')}});
document.getElementById('importData').addEventListener('change',async e=>{try{const x=JSON.parse(await e.target.files[0].text());if(!x||typeof x!=='object'||!Array.isArray(x.projects)||!Array.isArray(x.skills))throw Error();data={...structuredClone(DEFAULTS),...x};save();renderEditor()}catch{alert('This file is not a valid portfolio backup.')}e.target.value=''});
document.getElementById('resetData').addEventListener('click',()=>{if(confirm('Reset all portfolio edits in this browser to the starter content?')){data=structuredClone(DEFAULTS);save();renderEditor()}});
document.getElementById('contactForm').addEventListener('submit',e=>{e.preventDefault();if(!data.email){currentTab='profile';openEditor();document.getElementById('editorContent').querySelector('[data-key="email"]')?.focus();return}const f=new FormData(e.currentTarget),body=`From: ${f.get('name')} (${f.get('reply')})\n\n${f.get('message')}`;location.href=`mailto:${encodeURIComponent(data.email)}?subject=${encodeURIComponent(f.get('subject'))}&body=${encodeURIComponent(body)}`});
['headerCV','heroCV'].forEach(id=>document.getElementById(id).addEventListener('click',e=>{e.preventDefault();downloadCV()}));
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeEditor()});
renderSite();

